// Valida o payload do CRM. O CRM envia UM lead por chamada:
// { lead_id, clientes_ocultos_id, clinica: { nome, whatsapp, telefone, cidade, estado } }
const body = $input.first().json.body;

if (!body || typeof body.lead_id !== 'string' || body.lead_id.trim() === '') {
  throw new Error('Payload inválido: lead_id ausente');
}

return [{
  json: {
    lead_id: body.lead_id,
    clientes_ocultos_id: body.clientes_ocultos_id ?? null,
    clinica: body.clinica ?? {},
  },
}];

// Sorteia uma das 3 variações de mensagem inicial e resolve o número de destino.
const entrada = $input.first().json;

const variacoes = [
  {
    id: 'A',
    texto: 'Oi, boa tarde! Tudo bem? Vi vocês aqui no Google e queria tirar umas dúvidas sobre vacinas pro meu filho de 6 meses. Vocês atendem?'
  },
  {
    id: 'B',
    texto: 'Olá! Tudo bem? Meu nome é Carlos, tô pesquisando umas vacinas particulares pro meu bebê de 6 meses e queria entender o que vocês oferecem. Pode me ajudar?'
  },
  {
    id: 'C',
    texto: 'Oi, boa tarde 😊 Tô buscando informação sobre vacinas particulares pra criança pequena (6 meses). Vocês podem me passar como funciona aí?'
  }
];

const sorteada = variacoes[Math.floor(Math.random() * variacoes.length)];

// Ajusta a saudação ao horário (BRT = UTC-3), com wrap correto de 0-23h.
const hora = ((new Date().getUTCHours() - 3) + 24) % 24;
let mensagem = sorteada.texto;
if (hora < 12) mensagem = mensagem.replace('boa tarde', 'bom dia');
else if (hora >= 18) mensagem = mensagem.replace('boa tarde', 'boa noite');

// Número de destino: whatsapp da clínica, com fallback para telefone.
const numero = String(entrada.whatsapp || entrada.telefone || '').replace(/\D/g, '');

return [{
  json: {
    ...entrada,
    variacao_id: sorteada.id,
    mensagem,
    numero,
  },
}];

parameters.query:
UPDATE clientes_ocultos
SET enviado_em = NOW(),
    mensagem_enviada = $2,
    status = 'aguardando_resposta'
WHERE lead_id = $1 AND enviado_em IS NULL;
SELECT 1 AS ok;

