// Lead não elegível para disparo — registra o motivo e encerra sem erro.
const j = $input.first().json;
let motivo = 'desconhecido';
if (j.deleted_at) motivo = 'lead deletado';
else if (j.enviado_em) motivo = 'cliente oculto já enviado anteriormente';
else if (!j.whatsapp && !j.telefone) motivo = 'clínica sem whatsapp/telefone';

return [{ json: { lead_id: j.lead_id, skipped: true, motivo } }];
